The key is absent, and the loop counts one comparison per midpoint it examines. What integer does the program print? Respond with the integer only.

import java.util.Arrays;

public class A54 {
    // must print: 2
    public static void main(String[] args) {
        int[] sorted = {1, 3, 5, 7, 9};
        int key = 6;
        int lo = 0;
        int hi = sorted.length - 1;
        int comparisons = 0;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            comparisons++;
            if (sorted[mid] == key) {
                break;
            } else if (sorted[mid] < key) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        System.out.println(comparisons);
    }
}

